1	// src/lib/bericht/netzanschlussAblauf.js – Bericht-Baustein für den Ablauf-Begleiter Netzanschluss
2	// (Welle 4, Paket NETZ2). Eingebunden in src/lib/bericht/neuRechnen.js (RECHNER.netzanschluss).
3	//
4	// Der Bericht enthält den Schritt-für-Schritt-Ablauf des gewählten Landes mit Dokumenten-Checkliste,
5	// Status (erledigt / als Nächstes / offen), den belegten Fristen (nur DE, § 8 EEG) und den typischen
6	// Ablehnungsgründen samt Gegenmitteln. KEINE Geldwerte in keinem Land: Für Kostenspannen des
7	// Netzanschlusses liegt kein geprüfter Wert im Faktenregister – der Rechner auf der Seite bleibt
8	// eine eigene, als grobe Orientierung gekennzeichnete Schätzung und wird hier nicht wiederholt.
9	
10	import { ABLAUF_LAENDER, rechneAblauf, schrittIds } from "@/lib/rechner/netzanschlussAblauf";
11	import { PlattformFehler } from "@/lib/plattform/fehler";
12	
13	const LAND_NAME = { DE: "Deutschland", AT: "Österreich", CH: "Schweiz" };
14	const ALLE_SCHRITTE = schrittIds();
15	
16	/** Feldregeln im Format von neuRechnen.js */
17	export function regelnNetzanschlussAblauf({ mehrfach }) {
18	  return { erledigt: mehrfach(ALLE_SCHRITTE) };
19	}
20	
21	/** Erledigte Schritte müssen zum Land gehören (sonst 422) */
22	export function landPruefenNetzanschlussAblauf(e, land) {
23	  const l = String(land || "").toLowerCase();
24	  if (!ABLAUF_LAENDER.includes(l)) throw new PlattformFehler(422, "Bitte ein Land angeben (DE, AT oder CH).", "land");
25	  const gueltig = new Set(schrittIds(l));
26	  for (const id of e.erledigt || []) {
27	    if (!gueltig.has(id)) throw new PlattformFehler(422, "Schritt und Land passen nicht zusammen.", "eingabe");
28	  }
29	}
30	
31	/** Normalisierte Eingaben: erledigt in Ablauf-Reihenfolge (Grundlage der Prüf-ID) */
32	export function normalisierenNetzanschlussAblauf(e, land) {
33	  const reihenfolge = schrittIds(String(land).toLowerCase());
34	  const gesetzt = new Set(e.erledigt || []);
35	  return { erledigt: reihenfolge.filter((id) => gesetzt.has(id)) };
36	}
37	
38	export function rechneNetzanschlussAblauf(e, land) {
39	  return rechneAblauf({ land: String(land).toLowerCase(), erledigt: e.erledigt || [] });
40	}
41	
42	const kz = (label, wert, zusatz = "") => ({ label, wert, zusatz });
43	const STATUS_TEXT = { erledigt: "erledigt", aktiv: "als Nächstes", offen: "offen" };
44	const STATUS_STUFE = { erledigt: "gut", aktiv: "pruefen", offen: "info" };
45	
46	/** Zusammenfassung für die Berichtsseite (nur Formatierung) */
47	export function zusammenfassungNetzanschlussAblauf(r, e, land) {
48	  const offeneDokumente = r.schritte.filter((s) => s.status !== "erledigt").reduce((n, s) => n + s.dokumente.length, 0);
49	  return {
50	    kennzahlen: [
51	      kz("Verfahren", r.verfahren, LAND_NAME[land]),
52	      kz("Stand", `${r.anzahlErledigt} von ${r.anzahl} Schritten`, r.fertig ? "alle Schritte abgehakt" : `als Nächstes: ${r.naechster.titel}`),
53	      kz("Offene Unterlagen", String(offeneDokumente), "Dokumente der noch offenen Schritte"),
54	      ...(land === "DE"
55	        ? [kz("Gesetzliche Fristen", "§ 8 Abs. 5 und 6 EEG", r.schritte.find((s) => s.frist && s.id === "de-pruefung")?.frist.de || "")]
56	        : [kz("Fristen", "beim Netzbetreiber erfragen", "kein geprüfter Wert – siehe Hinweis")]),
57	    ],
58	    eingabenText: [
59	      ["Land", LAND_NAME[land]],
60	      ["Abgehakte Schritte", r.anzahlErledigt ? r.schritte.filter((s) => s.status === "erledigt").map((s) => s.titel).join("; ") : "noch keine"],
61	    ],
62	    rechenweg: [
63	      "Der Begleiter hakt die Schritte des Verfahrens in Ihrem Land ab; der erste nicht erledigte Schritt ist „als Nächstes“ markiert.",
64	      land === "DE"
65	        ? "Fristen: Nach § 8 Abs. 5 EEG muss der Netzbetreiber unverzüglich einen Zeitplan übermitteln; das Ergebnis der Netzverträglichkeitsprüfung samt Kostenvoranschlag folgt nach § 8 Abs. 6 EEG innerhalb der gesetzlichen Frist ab vollständigem Begehren."
66	        : r.fristHinweis,
67	      "Kosten nennt dieser Bericht bewusst nicht: Für belegte Kostenspannen des Netzanschlusses liegt kein geprüfter Wert im Faktenregister. Der Rechner auf der Seite liefert eine eigene, als grobe Orientierung gekennzeichnete Schätzung.",
68	    ],
69	    tabelle: null,
70	    listen: [
71	      {
72	        titel: "Ablauf mit Dokumenten-Checkliste",
73	        art: "schritte",
74	        eintraege: r.schritte.map((s) => ({
75	          titel: `Schritt ${s.nummer}: ${s.titel}`,
76	          stufe: STATUS_STUFE[s.status],
77	          stufeText: STATUS_TEXT[s.status],
78	          text: `${s.text}${s.frist ? ` Frist: ${s.frist.de}` : ""} Unterlagen: ${s.dokumente.map((x) => x.de).join("; ")}.`,
79	        })),
80	      },
81	      {
82	        titel: "Typische Ablehnungsgründe – und was dann hilft",
83	        art: "ablehnungen",
84	        eintraege: r.ablehnungen.map((a) => ({ titel: a.grund, text: a.hilfe })),
85	      },
86	    ],
87	    hinweise: [
88	      "Fachliche Orientierung, keine Rechtsberatung. Verbindlich sind die Auskünfte und Bedingungen des zuständigen Netzbetreibers.",
89	      ...(r.fristHinweis ? [r.fristHinweis] : []),
90	    ],
91	  };
92	}
